export function paginar(items, pagina, porPagina = 10) {
  const totalPaginas = Math.round(items.length / porPagina);
  const inicio = pagina * porPagina;
  const fin = inicio + porPagina;

  return {
    datos: items.slice(inicio, fin),
    pagina,
    totalPaginas,
    hayAnterior: pagina > 1,
    haySiguiente: pagina < totalPaginas,
  };
}

export function rangoTexto(pagina, porPagina, total) {
  const desde = (pagina - 1) * porPagina + 1;
  const hasta = Math.min(pagina * porPagina, total);
  return `Mostrando ${desde} a ${hasta} de ${total}`;
}
